364	// ---- prune ----------------------------------------------------------------------------------------------------
365	
366	export interface PruneOptions { dryRun?: boolean; minAgeMs?: number; limit?: number; discardIgnored?: boolean }
367	
368	const DAY_MS = 86_400_000;
369	const REPORT_LINES = 40;
370	
371	export function parseAge(text: string): number {
372	  const match = /^(\d+)([smhdw])$/.exec(text);
373	  if (!match) throw new WorktreeError("--min-age must look like 30m, 12h, 1d or 2w");
374	  const unit = { s: 1000, m: 60_000, h: 3_600_000, d: DAY_MS, w: 7 * DAY_MS }[match[2] as "s"];
375	  return Number(match[1]) * unit;
376	}
377	
378	export function pruneWorktrees(ctx: WorktreeContext, options: PruneOptions = {}): CommandResult {
379	  const minAge = options.minAgeMs ?? DAY_MS;
380	  const limit = Math.max(1, options.limit ?? 100);
381	  const repo = openRepo(ctx.cwd);
382	  const here = currentEntry(repo);
383	  const target = defaultBranch(repo);
384	  const targetSha = target ? resolveBranchCommit(repo, target) : undefined;
385	  if (!targetSha) throw new WorktreeError("this repository has no default branch to compare against");
386	
387	  const lines: string[] = [];
388	  const counts = { removed: 0, kept: 0, young: 0, stale: 0 };
389	  let limited = false;
390	  const label = (entry: WorktreeEntry) => (entry.branch ? shownBranch(entry.branch) : shownPath(ctx.home, entry.path));
391	  const keep = (entry: WorktreeEntry, why: string) => { counts.kept++; lines.push(`kept ${label(entry)}: ${why}`); };
392	  const now = Date.now();
393	
394	  for (const entry of repo.entries) {
395	    if (entry.isMain || entry === here) continue;
396	    if (counts.removed >= limit) { limited = true; break; }
397	    if (entry.prunable && entry.locked) { keep(entry, "stale but locked"); continue; }
398	    if (entry.prunable) {
399	      // A hand-deleted worktree is judged like any other. A detached one may hold the only reference to commits in its
400	      // administrative HEAD and reflog, so it goes only if that HEAD is integrated and old enough; a branch worktree's
401	      // commits live on its branch, which stays. Only the selected entries are cleared, never a global `worktree prune`.
402	      try {
403	        const stamp = Number(gitOut(repo.cwd, ["log", "-1", "--format=%ct", "--end-of-options", entry.head], { timeoutMs: 5000 })) * 1000;
404	        if (entry.detached && now - stamp < minAge) { counts.young++; continue; }
405	        const reason = entry.detached ? integratedReason(repo, entry.head, targetSha) : "branch kept";
406	        if (!reason) { keep(entry, `stale, but its detached HEAD is not merged into ${shownBranch(target!)}`); continue; }
407	        if (!options.dryRun) clearStaleEntry(repo, entry);
408	        counts.stale++;
409	        counts.removed++;
410	        lines.push(`${options.dryRun ? "would clear" : "cleared"} stale ${label(entry)} (${reason})`);
411	      } catch (err) {
412	        keep(entry, redactSecrets((err as Error).message).slice(0, 160));
413	      }
414	      continue;
415	    }
416	    if (entry.locked) { keep(entry, "locked"); continue; }
417	    if (isSpeculativeEntry(repo, entry)) { keep(entry, "speculative task worktree"); continue; }
418	    try {
419	      const touched = Math.max(fs.statSync(entry.path).mtimeMs, Number(gitOut(repo.cwd, ["log", "-1", "--format=%ct", "--end-of-options", entry.head], { timeoutMs: 5000 })) * 1000);
420	      if (now - touched < minAge) { counts.young++; continue; }
421	      const reason = integratedReason(repo, entry.head, targetSha);
422	      if (!reason) { keep(entry, `not merged into ${shownBranch(target!)}`); continue; }
423	      const dirty = statusOf(entry.path, { ignored: true, ignoreSubmodules: "none" });
424	      if (dirty.total > 0) { keep(entry, `dirty (${dirty.staged + dirty.modified} changed, ${dirty.untracked} untracked)`); continue; }
425	      if (dirty.ignored > 0 && !options.discardIgnored) { keep(entry, `${dirty.ignored} ignored path(s); pass --discard-ignored to prune it anyway`); continue; }
426	      if (options.dryRun) {
427	        counts.removed++;
428	        lines.push(`would remove ${label(entry)} (integrated: ${reason})`);
429	        continue;
430	      }
431	      removeOne(ctx, entry.path, { discardIgnored: dirty.ignored > 0 });
432	      counts.removed++;
433	      lines.push(`removed ${label(entry)} (integrated: ${reason})`);
434	    } catch (err) {
435	      keep(entry, redactSecrets((err as Error).message).slice(0, 160));
436	    }
437	  }
438	
439	  const summary = `${options.dryRun ? "Would remove" : "Removed"} ${counts.removed}, kept ${counts.kept}, ${counts.young} younger than the minimum age${counts.stale ? `, ${counts.stale} stale registration(s) ${options.dryRun ? "would be pruned" : "pruned"}` : ""}.`;
440	  const shown = lines.slice(0, REPORT_LINES);
441	  if (lines.length > REPORT_LINES) shown.push(`... ${lines.length - REPORT_LINES} more lines`);
442	  if (limited) shown.push(`stopped at the limit of ${limit} removals; run prune again for more`);
443	  return { success: true, output: [...shown, summary].join("\n"), data: { ...counts, limited } };
444	}
