1	/**
2	 * Host-side Git on a worktree the sandboxed agent can write to. The agent can rewrite the worktree's `.git` pointer (or
3	 * plant a nested repository); Git would then read the planted repository's configuration on the host, where a
4	 * `filter.*.clean` or `gpg.program` setting is a command. Every host-side call must refuse such a worktree first.
5	 * Also: merge races that another terminal can win between the checks and the mutation.
6	 */
7	import { test } from "node:test";
8	import assert from "node:assert/strict";
9	import fs from "node:fs";
10	import os from "node:os";
11	import path from "node:path";
12	import { execFileSync } from "node:child_process";
13	import { runWorktreeCommand } from "../src/worktrunk/command.js";
14	import { mergeSeams } from "../src/worktrunk/merge.js";
15	
16	function git(cwd: string, ...args: string[]): string {
17	  return execFileSync("git", args, { cwd, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }).trim();
18	}
19	
20	function fixture(name = "feat/t") {
21	  const root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "nexus-wttrust-")));
22	  const repo = path.join(root, "proj");
23	  const home = path.join(root, "home");
24	  fs.mkdirSync(repo);
25	  fs.mkdirSync(home);
26	  git(repo, "init", "-q", "-b", "main");
27	  git(repo, "config", "user.email", "t@example.com");
28	  git(repo, "config", "user.name", "T");
29	  git(repo, "config", "commit.gpgsign", "false");
30	  fs.writeFileSync(path.join(repo, ".gitignore"), "ignored.log\n");
31	  fs.writeFileSync(path.join(repo, "a.txt"), "one\n");
32	  git(repo, "add", ".");
33	  git(repo, "commit", "-q", "-m", "init");
34	  const made = runWorktreeCommand(["switch", "-c", name, "--no-copy"], { cwd: repo, home, readOnly: false });
35	  assert.equal(made.success, true, made.output);
36	  const dir = path.join(repo, ".nexus", "worktrees", name.replace("/", "-"));
37	  return { root, repo, home, dir, merge: (extra: string[] = []) => runWorktreeCommand(["merge", "--no-verify-receipt", "--reason", "trust fixture", ...extra], { cwd: dir, home, readOnly: false }), cleanup: () => fs.rmSync(root, { recursive: true, force: true }) };
38	}
39	
40	/** Rewrites the worktree's `.git` pointer to a repository planted INSIDE the worktree whose config runs `marker`-writing commands. */
41	function plantRepository(f: ReturnType<typeof fixture>, branch: string, config: string[]): string {
42	  const marker = path.join(f.root, "MARKER");
43	  const plant = path.join(f.dir, "plant");
44	  fs.mkdirSync(plant);
45	  git(plant, "init", "-q", "-b", "main");
46	  git(plant, "config", "user.email", "t@example.com");
47	  git(plant, "config", "user.name", "T");
48	  fs.writeFileSync(path.join(plant, "seed"), "seed\n");
49	  git(plant, "add", "seed");
50	  git(plant, "-c", "commit.gpgsign=false", "commit", "-q", "-m", "seed");
51	  git(plant, "branch", branch);
52	  git(plant, "worktree", "add", "-q", "-b", `${branch}-wt`, path.join(f.root, "planted-wt"));
53	  const admin = path.join(plant, ".git", "worktrees", "planted-wt");
54	  fs.writeFileSync(path.join(admin, "gitdir"), path.join(f.dir, ".git") + "\n");
55	  fs.writeFileSync(path.join(admin, "HEAD"), `ref: refs/heads/${branch}\n`);
56	  for (const line of config) git(plant, "config", ...line.replace("@MARKER@", marker).split("\u0000"));
57	  fs.writeFileSync(path.join(f.dir, ".git"), `gitdir: ${admin}\n`);
58	  fs.writeFileSync(path.join(f.dir, ".gitattributes"), "* filter=plant\n");
59	  fs.writeFileSync(path.join(f.dir, "a.txt"), "edited by the agent\n");
60	  return marker;
61	}
62	
63	test("a worktree whose .git pointer leads into a repository planted inside it is refused before any filter or program runs", () => {
64	  const f = fixture();
65	  try {
66	    const marker = plantRepository(f, "feat/t", [
67	      `filter.plant.clean\u0000sh -c 'echo ran > @MARKER@; cat'`,
68	      `commit.gpgsign\u0000true`,
69	      `gpg.program\u0000sh -c 'echo gpg > @MARKER@'`,
70	    ]);
71	    const r = f.merge();
72	    assert.equal(fs.existsSync(marker), false, `a planted configuration command ran on the host: ${r.output}`);
73	    assert.equal(r.success, false, r.output);
74	    assert.match(r.output, /not a trusted worktree/i);
75	  } finally { f.cleanup(); }
76	});
77	
78	test("a clean multi-commit source: content force-added after the snapshot refuses the merge and keeps the worktree", () => {
79	  const f = fixture("feat/two");
80	  try {
81	    for (const n of ["x", "y"]) { fs.writeFileSync(path.join(f.dir, n), n); git(f.dir, "add", n); git(f.dir, "commit", "-q", "-m", n); }
82	    mergeSeams.preMerge = () => { fs.writeFileSync(path.join(f.dir, "ignored.log"), "staged on purpose\n"); git(f.dir, "add", "-f", "ignored.log"); };
83	    let r;
84	    try { r = f.merge(); } finally { delete mergeSeams.preMerge; }
85	    assert.equal(r.success, false, r.output);
86	    assert.match(r.output, /index changed|staged/i);
87	    assert.equal(fs.existsSync(path.join(f.dir, "ignored.log")), true, "the worktree and the file are kept");
88	    assert.equal(git(f.repo, "ls-tree", "-r", "--name-only", "HEAD").split("\n").includes("x"), false, "nothing was merged");
89	  } finally { f.cleanup(); }
90	});
91	
92	test("a target checkout switched to another branch at the same commit is refused, not fast-forwarded under main's name", () => {
93	  const f = fixture("feat/tgt");
94	  try {
95	    fs.writeFileSync(path.join(f.dir, "w.txt"), "w\n");
96	    git(f.dir, "add", "w.txt");
97	    git(f.dir, "commit", "-q", "-m", "work");
